-- 75 The Controls Room: rebinding at runtime. Input.get_just_pressed()
-- names what went down this frame as a binding; Input.set_bindings takes
-- it; Save.set + Save.commit keep it for the next run. The ship flies by
-- the same actions, so a new binding is felt at once. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/75-the-controls-room.scene"
local ACTIONS = {
    { "cr_thrust", "THRUST", { "W", "Pad0_A" } },
    { "cr_left", "TURN LEFT", { "A", "Pad0_LeftStickX-" } },
    { "cr_right", "TURN RIGHT", { "D", "Pad0_LeftStickX+" } },
    { "cr_fire", "FIRE", { "Space", "Pad0_X" } },
    { "cr_shield", "SHIELD", { "S", "Pad0_Y" } },
}
local SLOT = "controls_room"
local FX, FY, FW, FH = 300.0, -10.0, 520.0, 460.0
local captions = true
local rows, cursor, ship, flame, shield, saved_text = {}, nil, nil, nil, nil, nil
local shots = {}
local pick, capturing, saved_t, t = 1, false, 0, 0
local x, y, vx, vy, a, cool = FX, FY, 0, 0, math.pi / 2, 0

-- The bindings as this script last set them. `Input.set_bindings` is
-- deferred - `Input.get_bindings` answers the old keys until the frame is
-- over - so what is saved comes from here, not from asking back.
local current = {}

local function bind(name, keys)
    current[name] = keys
    Input.set_bindings(name, keys)
end

local function save()
    Save.set(SLOT, "bindings", current)
    Save.commit(SLOT)
    saved_t = 2.0
end

local function defaults()
    for _, act in ipairs(ACTIONS) do bind(act[1], act[3]) end
end

function init(entity)
    for i = 1, #ACTIONS do rows[i] = Entity.find_by_name("Row" .. (i - 1) .. "Keys") end
    cursor = Entity.find_by_name("Cursor")
    ship = Entity.find_by_name("Ship")
    flame = Entity.find_by_name("Flame")
    shield = Entity.find_by_name("Shield")
    saved_text = Entity.find_by_name("Saved")
    for k = 0, 5 do shots[k + 1] = { e = Entity.find_by_name("Shot" .. k), life = 0, x = 0, y = 0, vx = 0, vy = 0 } end
    -- What the last run saved, and the defaults for anything it did not.
    defaults()
    local saved = Save.get(SLOT, "bindings")
    if type(saved) == "table" then
        for name, keys in pairs(saved) do
            if type(keys) == "table" then bind(name, keys) end
        end
    end
end

local function wrap(v, lo, hi)
    if v < lo then return hi - (lo - v) end
    if v > hi then return lo + (v - hi) end
    return v
end

function update(entity, dt)
    -- While listening, every key is a candidate binding - H and Escape too,
    -- which would otherwise leave for the hub.
    if not capturing then nav.tick(SCENE) end
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt
    -- The menu.
    local pressed = Input.get_just_pressed()
    if capturing then
        if Input.is_key_just_pressed("Escape") then
            capturing = false
        elseif #pressed > 0 then
            bind(ACTIONS[pick][1], { pressed[1] })
            capturing = false
            save()
        end
    else
        if Input.is_key_just_pressed("Up") then pick = (pick - 2) % #ACTIONS + 1 end
        if Input.is_key_just_pressed("Down") then pick = pick % #ACTIONS + 1 end
        if Input.is_key_just_pressed("Enter") then capturing = true end
        if Input.is_key_just_pressed("Backspace") then defaults(); save() end
    end
    for i, act in ipairs(ACTIONS) do
        local e = rows[i]
        if e then
            if capturing and i == pick then
                Text.set(e, (math.floor(t * 3) % 2 == 0) and "[color=#ffffff]> PRESS A KEY OR BUTTON <[/color]" or "")
            else
                Text.set(e, table.concat(current[act[1]] or {}, "  /  "))
            end
        end
    end
    if cursor then
        Transform.set_position(cursor, -300, 135 - (pick - 1) * 70)
        Sprite.set_color(cursor, 0.2, 0.6, 0.3, 0.18 + 0.08 * math.sin(t * 5))
    end
    saved_t = math.max(0, saved_t - dt)
    if saved_text then Text.set(saved_text, saved_t > 0 and "SAVED - it holds after a restart" or "") end

    -- The ship, by the actions.
    if Input.is_action_pressed("cr_left") then a = a + 3.2 * dt end
    if Input.is_action_pressed("cr_right") then a = a - 3.2 * dt end
    local thrust = Input.is_action_pressed("cr_thrust")
    if thrust then vx, vy = vx + math.cos(a) * 260 * dt, vy + math.sin(a) * 260 * dt end
    vx, vy = vx * (1 - 0.6 * dt), vy * (1 - 0.6 * dt)
    x = wrap(x + vx * dt, FX - FW / 2 + 20, FX + FW / 2 - 20)
    y = wrap(y + vy * dt, FY - FH / 2 + 20, FY + FH / 2 - 20)
    if ship then Transform.set_position(ship, x, y); Transform.set_rotation(ship, a - math.pi / 2) end
    if flame then
        Transform.set_position(flame, x - math.cos(a) * 26, y - math.sin(a) * 26)
        Transform.set_rotation(flame, a)
        Sprite.set_color(flame, 1.0, 0.6, 0.2, thrust and (0.7 + 0.3 * math.sin(t * 40)) or 0)
    end
    if shield then
        Transform.set_position(shield, x, y)
        Sprite.set_color(shield, 0.4, 0.8, 1.0, Input.is_action_pressed("cr_shield") and 0.8 or 0)
    end
    cool = cool - dt
    if Input.is_action_pressed("cr_fire") and cool <= 0 then
        for _, s in ipairs(shots) do
            if s.life <= 0 then
                s.life, s.x, s.y = 0.9, x + math.cos(a) * 24, y + math.sin(a) * 24
                s.vx, s.vy = vx + math.cos(a) * 420, vy + math.sin(a) * 420
                cool = 0.18
                break
            end
        end
    end
    for _, s in ipairs(shots) do
        if s.life > 0 then
            s.life = s.life - dt
            s.x = wrap(s.x + s.vx * dt, FX - FW / 2 + 6, FX + FW / 2 - 6)
            s.y = wrap(s.y + s.vy * dt, FY - FH / 2 + 6, FY + FH / 2 - 6)
            if s.e then Transform.set_position(s.e, s.x, s.life > 0 and s.y or -2000) end
        end
    end
end
